import{_ as a,o as n,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const y=JSON.parse('{"title":"解压和打包安卓DAT文件","description":"安卓 5.0 的卡刷包系统基本上都是在一个 dat 文件里面的。但是对于很多国内 ROM，要不就是植入了很多流氓软件，\\n要不就是有很多无用软件。我们可以通过解压 DAT 文件并进行修改然后再封装回去就完美啦～","frontmatter":{"title":"解压和打包安卓DAT文件","date":"2015-7-28 19:54","comments":true,"archives":2015,"tags":["notes"]},"headers":[],"relativePath":"posts/2015-07-28-compression-and-decompression-dat-files/index.md","filePath":"posts/2015/2015-07-28-Compression-and-Decompression-DAT-files.md"}'),o={name:"posts/2015-07-28-compression-and-decompression-dat-files/index.md"};function p(t,s,r,i,c,d){return n(),e("div",null,[...s[0]||(s[0]=[l(`<p>安卓 5.0 的卡刷包系统基本上都是在一个 dat 文件里面的。但是对于很多国内 ROM，要不就是植入了很多流氓软件， 要不就是有很多无用软件。我们可以通过解压 DAT 文件并进行修改然后再封装回去就完美啦～</p><h2 id="首先把-dat-解压成-img-镜像" tabindex="-1">首先把 DAT 解压成 IMG 镜像 <a class="header-anchor" href="#首先把-dat-解压成-img-镜像" aria-label="Permalink to &quot;首先把 DAT 解压成 IMG 镜像&quot;">​</a></h2><p>我们要使用<a href="https://github.com/xpirt/sdat2img" target="_blank" rel="noreferrer">sdat2img</a>工具把 DAT 文件转换成 IMG 镜像</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">./sdat2img</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">transfer_lis</span><span style="color:#24292E;">t</span><span style="color:#D73A49;">&gt;</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">system_new_fil</span><span style="color:#24292E;">e</span><span style="color:#D73A49;">&gt;</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">system_ext</span><span style="color:#D73A49;">4&gt;</span></span>
<span class="line"><span style="color:#6F42C1;">-</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">transfer_lis</span><span style="color:#24292E;">t</span><span style="color:#D73A49;">&gt;</span><span style="color:#032F62;"> =</span><span style="color:#032F62;"> input,</span><span style="color:#032F62;"> system.transfer.list</span><span style="color:#032F62;"> from</span><span style="color:#032F62;"> rom</span><span style="color:#032F62;"> zip</span></span>
<span class="line"><span style="color:#6F42C1;">-</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">system_new_fil</span><span style="color:#24292E;">e</span><span style="color:#D73A49;">&gt;</span><span style="color:#032F62;"> =</span><span style="color:#032F62;"> input,</span><span style="color:#032F62;"> system.new.dat</span><span style="color:#032F62;"> from</span><span style="color:#032F62;"> rom</span><span style="color:#032F62;"> zip</span></span>
<span class="line"><span style="color:#6F42C1;">-</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">system_ext</span><span style="color:#D73A49;">4&gt;</span><span style="color:#032F62;"> =</span><span style="color:#032F62;"> output</span><span style="color:#032F62;"> ext4</span><span style="color:#032F62;"> raw</span><span style="color:#032F62;"> image</span><span style="color:#032F62;"> file</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>一个很简单的例子:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">./sdat2img</span><span style="color:#032F62;"> system.transfer.list</span><span style="color:#032F62;"> system.new.dat</span><span style="color:#032F62;"> system.img</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>新生成的 IMG 镜像便是我们下一步需要的.</p><h2 id="挂载-img-镜像" tabindex="-1">挂载 IMG 镜像 <a class="header-anchor" href="#挂载-img-镜像" aria-label="Permalink to &quot;挂载 IMG 镜像&quot;">​</a></h2><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">sudo</span><span style="color:#032F62;"> mount</span><span style="color:#005CC5;"> -t</span><span style="color:#032F62;"> ext4</span><span style="color:#005CC5;"> -o</span><span style="color:#032F62;"> loop</span><span style="color:#032F62;"> system.img</span><span style="color:#032F62;"> /mnt/android</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这时候你可以在系统的 /mnt/android 目录下看到文件的具体内容然后进行修改了.</p><h2 id="打包回-img-镜像" tabindex="-1">打包回 IMG 镜像 <a class="header-anchor" href="#打包回-img-镜像" aria-label="Permalink to &quot;打包回 IMG 镜像&quot;">​</a></h2><p>把修改好的内容打包回去需要使用<a href="https://github.com/EpicAOSP/make_ext4" target="_blank" rel="noreferrer">make_ext4</a>工具</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">./make_ext4fs</span><span style="color:#005CC5;"> -T</span><span style="color:#005CC5;"> 0</span><span style="color:#005CC5;"> -S</span><span style="color:#032F62;"> file_contexts</span><span style="color:#005CC5;"> -l</span><span style="color:#005CC5;"> 1073741824</span><span style="color:#005CC5;"> -a</span><span style="color:#032F62;"> system</span><span style="color:#032F62;"> system_new.img</span><span style="color:#032F62;"> /mnt/android</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>file_contexts 文件是 ROM 本身提供的.后面的一串数字指的是打包的 IMG 文件的大小 1G</p><h2 id="封装成-dat-文件" tabindex="-1">封装成 DAT 文件 <a class="header-anchor" href="#封装成-dat-文件" aria-label="Permalink to &quot;封装成 DAT 文件&quot;">​</a></h2><p>封装仍需要使用工具 使用 <a href="https://mega.co.nz/#!IRAi0SKL!nof6p9JmFhGQNgnNmdEKWiEwZ9NOFUVv4q9BQZfM95w" target="_blank" rel="noreferrer">rimg2sdat</a></p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">./rimg2sdat</span><span style="color:#D73A49;"> &lt;</span><span style="color:#032F62;">system_im</span><span style="color:#24292E;">g</span><span style="color:#D73A49;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样就打包好了新的 DAT 文件,放入刷机 ROM.刷机即可~ 以上操作最好在 Linux 环境下,Win 下不保证成功.</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="http://forum.xda-developers.com/android/software-hacking/how-to-conver-lollipop-dat-files-to-t2978952" target="_blank" rel="noreferrer">XDA</a></p>`,20)])])}const b=a(o,[["render",p]]);export{y as __pageData,b as default};
